import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"LLMs.txt","description":"","frontmatter":{},"headers":[],"relativePath":"ai/llms.md","filePath":"ai/llms.md","lastUpdated":1791959953000}`),a={name:`ai/llms.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="llms-txt" tabindex="-1">LLMs.txt <a class="header-anchor" href="#llms-txt" aria-label="Permalink to “LLMs.txt”">​</a></h1><p>文档站在构建时产出一组给大语言模型读的机读资产，内容与站点正文同源。AI 工具读取它们即可了解 XiHan.Framework 的模块、API 与用法。</p><h2 id="可用资源" tabindex="-1">可用资源 <a class="header-anchor" href="#可用资源" aria-label="Permalink to “可用资源”">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://framework.docs.xihanfun.com/llms.txt" target="_blank" rel="noreferrer">llms.txt</a></td><td>索引：全部页面的标题、一句话摘要与地址，以及下列资产的入口</td></tr><tr><td><a href="https://framework.docs.xihanfun.com/llms-full.txt" target="_blank" rel="noreferrer">llms-full.txt</a></td><td>全站正文</td></tr><tr><td><a href="https://framework.docs.xihanfun.com/llms-guide.txt" target="_blank" rel="noreferrer">llms-guide.txt</a></td><td>开发指南：按能力域组织的用法与原理</td></tr><tr><td><a href="https://framework.docs.xihanfun.com/llms-packages.txt" target="_blank" rel="noreferrer">llms-packages.txt</a></td><td>模块总览：每个包的 API 清单与配置项全表</td></tr><tr><td><a href="https://framework.docs.xihanfun.com/ai/SKILL.md" target="_blank" rel="noreferrer">ai/SKILL.md</a></td><td>给 AI 编程工具的使用规范，见 <a href="./agents">For Agents</a></td></tr></tbody></table><p><strong>单页 Markdown</strong>：任何一页的站点地址后加 <code>.md</code> 即可取到这一页的 Markdown，如 <a href="https://framework.docs.xihanfun.com/guide/caching.md" target="_blank" rel="noreferrer">guide/caching.md</a>、<a href="https://framework.docs.xihanfun.com/packages/web-api.md" target="_blank" rel="noreferrer">packages/web-api.md</a>。每页正文上方的「取本页 Markdown」也指向它。</p><p><code>llms-full.txt</code> 体积较大，多数场景读 <code>llms.txt</code> 索引后按需取单页，或只取用到的分册。</p><h2 id="在-ai-工具中使用" tabindex="-1">在 AI 工具中使用 <a class="header-anchor" href="#在-ai-工具中使用" aria-label="Permalink to “在 AI 工具中使用”">​</a></h2><p>所有工具都可以用同一段提示词：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>阅读 https://framework.docs.xihanfun.com/llms.txt 了解 XiHan.Framework，写代码时按需读取其中列出的页面（站点地址后加 .md 取 Markdown），以文档为准，不要凭记忆写包名、模块类名与配置键。</span></span></code></pre></div><table tabindex="0"><thead><tr><th>工具</th><th>做法</th></tr></thead><tbody><tr><td>Claude Code</td><td>写进项目的 <code>CLAUDE.md</code>，或用 <code>/memory</code> 记下</td></tr><tr><td>Cursor</td><td>在对话中用 <code>@Docs</code> 添加 <code>https://framework.docs.xihanfun.com/llms.txt</code>，或写进 <code>.cursor/rules</code></td></tr><tr><td>Codex</td><td>写进项目的 <code>AGENTS.md</code></td></tr><tr><td>GitHub Copilot</td><td>写进 <code>.github/copilot-instructions.md</code></td></tr><tr><td>Windsurf</td><td>写进 <code>.windsurf/rules</code></td></tr></tbody></table><p>能运行命令或接入 MCP 的工具，优先用 <a href="./cli">CLI</a> 或 <a href="./mcp">MCP Server</a>：数据离线且与项目版本一致，配置节还能精确到属性的类型与缺省值；文档站上的资产对应最新发布的版本。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="./agents">For Agents</a> · <a href="./mcp">MCP Server</a> · <a href="./cli">CLI</a></li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};